def count_regular_bracket_sequences(n, s):
    m = len(s)

    # dp[i][j] will store the number of ways to form a valid sequence of length 2*i
    # with j open brackets left.
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # There's exactly one way to form an empty sequence with no open brackets left.
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(n + 1):
            # Add a closing bracket if there's an unmatched open bracket available.
            if j < n:
                dp[i][j] = dp[i - 1][j + 1]

            # Add an opening bracket if we haven't used all i pairs.
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD

    total_ways = 0

    for i in range(n - m + 1):
        # Calculate the number of valid bracket sequences of length 2n that
        # contain s[i:i+m] as a substring.
        valid_ways = dp[n][0]  # dp[n][0] means we have no unmatched brackets at the end.
        if valid_ways == 0:
            continue

        # Adjust the number of ways to account for s[i:i+m]
        open_count = 0
        close_count = 0
        for k in range(m):
            if s[k] == '(':
                open_count += 1
            else:
                close_count += 1
                if open_count > close_count:
                    valid_ways = 0
                    break

        if open_count < close_count:
            valid_ways = 0

        if valid_ways > 0:
            total_ways = (total_ways + valid_ways) % MOD

    return total_ways

